        def repl_match(pos):
            def func(x):
                if not isinstance(x, MatrixElement):
                    return False
                if x.args[pos] != i1:
                    return False
                if x.args[3-pos] == 0:
                    if x.args[0].shape[2-pos] == 1:
                        return True
                    else:
                        return False
                return True
